const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Jianghan District, Wuhan approximate bounds
  var jianghan = ee.Geometry.Polygon([
    [114.25, 30.57],
    [114.30, 30.57],
    [114.30, 30.62],
    [114.25, 30.62],
    [114.25, 30.57]
  ]);

  // 2. Data Acquisition - VIIRS DNB Monthly Composites
  var jan2020 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate('2020-01-01', '2020-01-31')
    .filterBounds(jianghan);

  var feb2020 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate('2020-02-01', '2020-02-29')
    .filterBounds(jianghan);

  // Check if collections exist
  var janSize = jan2020.size().getInfo();
  var febSize = feb2020.size().getInfo();

  console.log(`Jan 2020 Images: ${janSize}, Feb 2020 Images: ${febSize}`);

  if (janSize === 0 || febSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  var janImg = jan2020.first();
  var febImg = feb2020.first();

  // 3. Processing - Get pixel counts and mean radiance
  var janStats = janImg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: jianghan,
    scale: 1000,
    maxPixels: 1e9
  });

  var febStats = febImg.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: jianghan,
    scale: 1000,
    maxPixels: 1e9
  });

  var janMean = janStats.get('avg_rad').getInfo();
  var janCount = janStats.get('avg_rad_count').getInfo();
  var febMean = febStats.get('avg_rad').getInfo();
  var febCount = febStats.get('avg_rad_count').getInfo();

  console.log(`Jan 2020: Mean=${janMean?.toFixed(4)}, Pixels=${janCount}`);
  console.log(`Feb 2020: Mean=${febMean?.toFixed(4)}, Pixels=${febCount}`);

  // Check for valid pixels
  if (janCount === 0 || febCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Validation & Final Answer
  if (janMean === null || febMean === null || 
      isNaN(janMean) || isNaN(febMean) ||
      janMean < 0 || febMean < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare nighttime light intensity
  if (febMean < janMean) {
    console.log(`Nighttime lights decreased: ${janMean.toFixed(4)} -> ${febMean.toFixed(4)}`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`Nighttime lights same/increased: ${janMean.toFixed(4)} -> ${febMean.toFixed(4)}`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
